const e = $('⚙️ Einordnung-Einstellungen').first().json;
const fertig = {};
for (const i of $('Bisherige Einordnung laden').all()) if (i.json.job_id) fertig[i.json.job_id] = i.json.bewertet_am || '';
// Nur bewertete Stellen, die noch keine (oder eine veraltete) Einordnung haben
const offen = $('Alle Stellen laden')
  .all()
  .map((i) => i.json)
  .filter((r) => r && r.id && r.bewertung && r.bewertung !== 'fehler')
  .filter((r) => !(r.id in fertig) || fertig[r.id] !== String(r.bewertet_am || ''))
  .slice(0, Number(e.max_stellen) || 2000);
if (!offen.length) return [{ json: { _leer: true } }];

const vorlage = String($json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [system, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
const kurz = (t, n) => String(t || '').replace(/\s+/g, ' ').trim().slice(0, n);
const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['einordnungen'],
  properties: {
    einordnungen: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['id', 'bereich', 'hauptgrund', 'beschreibung', 'kurz'],
        properties: {
          id: { type: 'integer' },
          bereich: { type: 'string', enum: ["Entwicklung","IT-Betrieb / Admin / Security","Data / KI","Technischer Support","Kundenservice","Customer Success / Onboarding","Sales – Beratung / Inbound","Sales – Kaltakquise / Outbound","Marketing / Content","Projekt / Produkt / Operations","Finanzen / Recht / HR","Design / Video","Sonstiges"] },
          hauptgrund: { type: 'string', enum: ["kein großes Problem","Remote nur bestimmte Länder","Präsenz / Hybrid","Wohnsitz / Arbeitserlaubnis","Rolle passt nicht","Erfahrung / Skills fehlen","Festanstellung / Vertragsform","Gehalt / nur Provision","Sprache","Kaltakquise / Callcenter","Firma auf Ausschlussliste","Unseriös / Warnsignale","Info fehlt","Sonstiges"] },
          beschreibung: { type: 'string', enum: ['ausreichend', 'dünn'] },
          kurz: { type: 'string' },
        },
      },
    },
  },
};
const groesse = Number(e.paket_groesse) || 25;
const pakete = [];
for (let s = 0; s < offen.length; s += groesse) {
  const teil = offen.slice(s, s + groesse);
  const stellen = teil
    .map((r) =>
      [
        `--- id ${r.id}`,
        `Jobtitel: ${kurz(r.jobtitel || r.linktext, 160)}`,
        `Firma: ${kurz(r.firma, 80)} | Remote: ${r.remote || '-'} | Vertrag: ${kurz(r.vertragsform, 60) || '-'}`,
        `Remote-Regel: ${kurz(r.remote_regel_wortlaut, 200) || '-'}`,
        `Bewertung: ${r.bewertung} (Score ${r.passung_score || '-'}, Pflichtkriterien: ${r.pflichtkriterien_erfuellt || '-'})`,
        `Begründung: ${kurz(String(r.bewertung_begruendung || '').replace(/\s*\[[^\]]*\]/g, ''), 600)}`,
        `Lücken: ${kurz(r.luecken, 200) || '-'}`,
      ].join('\n')
    )
    .join('\n\n');
  pakete.push({
    json: {
      system,
      anfrage: anfrage.replace('{{STELLEN}}', () => stellen),
      seitentext: '',
      schema: SCHEMA,
      funktion: 'einordnung', // eigenes Modell laut ⚙️ Einstellungen (fehlt es: wie "fakten")
      claude_effort_override: 'low',
      ollama_denken_override: 'aus',
      kontext: { ids: teil.map((r) => r.id), bewertet_am: Object.fromEntries(teil.map((r) => [r.id, String(r.bewertet_am || '')])) },
    },
  });
}
return pakete;

const r = $json;
const k = r.kontext || {};
const erlaubt = new Set(k.ids || []);
const jetzt = new Date().toISOString();
if (!r.ok || !r.daten || !Array.isArray(r.daten.einordnungen)) return [{ json: { _fehler: r.fehler || 'keine Antwort' } }];
const zeilen = r.daten.einordnungen
  .filter((x) => erlaubt.has(Number(x.id)))
  .map((x) => ({
    json: {
      job_id: Number(x.id),
      bereich: String(x.bereich || 'Sonstiges'),
      hauptgrund: String(x.hauptgrund || 'Sonstiges'),
      beschreibung: String(x.beschreibung || ''),
      kurz: String(x.kurz || '').slice(0, 120),
      bewertet_am: (k.bewertet_am || {})[x.id] || '',
      modell: `${r.anbieter}:${r.modell}`,
      eingeordnet_am: jetzt,
    },
  }));
return zeilen.length ? zeilen : [{ json: { _fehler: 'leere Antwort' } }];
